"""Archive generation for the chezmoi-compatible command line."""
import gzip
import io
import os
import tarfile
import zipfile
from pathlib import Path


def _target_name(name: str) -> str | None:
    """Decode the common chezmoi source-state filename prefixes."""
    parts = []
    for part in name.split("/"):
        if part.startswith(".chezmoi") or part in (".git", ".gitignore"):
            return None
        for prefix in ("private_", "executable_", "readonly_", "create_", "modify_", "remove_", "symlink_"):
            if part.startswith(prefix):
                part = part[len(prefix):]
                break
        if part.startswith("dot_"):
            part = "." + part[4:]
        if part.endswith(".tmpl"):
            part = part[:-5]
        parts.append(part)
    return "/".join(parts)


def _entries(src: Path):
    ignored = set()
    ignore_file = src / ".chezmoiignore"
    if ignore_file.is_file():
        ignored = {line.strip() for line in ignore_file.read_text().splitlines()
                   if line.strip() and not line.lstrip().startswith("#")}
    for root, dirs, files in os.walk(src, followlinks=False):
        dirs[:] = sorted(d for d in dirs if d != ".git")
        for name in sorted(dirs + files):
            path = Path(root) / name
            rel = path.relative_to(src).as_posix()
            target = _target_name(rel)
            if target is not None and target not in ignored and not any(target.startswith(x.rstrip("/") + "/") for x in ignored):
                yield path, target


def make_archive(src: str, fmt: str = "tar.gz") -> bytes:
    srcpath = Path(src)
    fmt = fmt.lower()
    if fmt in ("tgz", "gzip"):
        fmt = "tar.gz"
    if fmt in ("tar", "tar.gz"):
        raw = io.BytesIO()
        with tarfile.open(fileobj=raw, mode="w") as tf:
            for path, target in _entries(srcpath):
                info = tf.gettarinfo(str(path), arcname=target)
                base = path.name
                if base.startswith("symlink_"):
                    info.type = tarfile.SYMTYPE
                    info.linkname = path.read_text().strip()
                    info.size = 0
                    tf.addfile(info)
                elif info.isfile():
                    if base.startswith("executable_"):
                        info.mode = 0o755
                    if base.startswith("readonly_"):
                        info.mode = 0o444
                    if base.startswith("private_"):
                        info.mode = 0o600
                    with path.open("rb") as f:
                        tf.addfile(info, f)
                else:
                    tf.addfile(info)
        data = raw.getvalue()
        if fmt == "tar.gz":
            return gzip.compress(data, mtime=0)
        return data
    if fmt == "zip":
        raw = io.BytesIO()
        with zipfile.ZipFile(raw, "w", zipfile.ZIP_DEFLATED) as zf:
            for path, target in _entries(srcpath):
                if path.is_symlink():
                    zf.writestr(target, os.readlink(path))
                elif path.is_file():
                    zf.write(path, target)
                else:
                    zf.writestr(target.rstrip("/") + "/", "")
        return raw.getvalue()
    raise ValueError("unsupported archive format")


def run_archive(args, source: str, output=None) -> int:
    """Handle archive options; args excludes the command name and global flags."""
    fmt = "tar.gz"
    outpath = None
    positional = []
    i = 0
    while i < len(args):
        arg = args[i]
        if arg in ("-f", "--format") and i + 1 < len(args):
            i += 1
            fmt = args[i]
        elif arg.startswith("--format="):
            fmt = arg.split("=", 1)[1]
        elif arg in ("-o", "--output") and i + 1 < len(args):
            i += 1
            outpath = args[i]
        elif arg.startswith("--output="):
            outpath = arg.split("=", 1)[1]
        elif arg == "-z" or arg == "--gzip":
            fmt = "tar.gz"
        elif arg.startswith("-"):
            pass
        else:
            positional.append(arg)
        i += 1
    try:
        data = make_archive(source, fmt)
    except (OSError, ValueError) as e:
        import sys
        print(f"chezmoi: {e}", file=sys.stderr)
        return 1
    if outpath:
        Path(outpath).write_bytes(data)
    elif output is not None:
        output.buffer.write(data)
    else:
        import sys
        sys.stdout.buffer.write(data)
    return 0
"""Small, deterministic subset of chezmoi's generate commands."""

INSTALL_SH = '''#!/bin/sh

# -e: exit on error
# -u: exit on unset variables
set -eu

if ! chezmoi="$(command -v chezmoi)"; then
	bin_dir="${HOME}/.local/bin"
	chezmoi="${bin_dir}/chezmoi"
	echo "Installing chezmoi to '${chezmoi}'" >&2
	if command -v curl >/dev/null; then
		chezmoi_install_script="$(curl -fsSL https://get.chezmoi.io)"
	elif command -v wget >/dev/null; then
		chezmoi_install_script="$(wget -qO- https://get.chezmoi.io)"
	else
		echo "To install chezmoi, you must have curl or wget installed." >&2
		exit 1
	fi
	sh -c "${chezmoi_install_script}" -- -b "${bin_dir}"
	unset chezmoi_install_script bin_dir
fi

# POSIX way to get script's dir: https://stackoverflow.com/a/29834779/12156188
script_dir="$(cd -P -- "$(dirname -- "$(command -v -- "$0")")" && pwd -P)"

set -- init --apply --source="${script_dir}"

echo "Running 'chezmoi $*'" >&2
# exec: replace current process with chezmoi
exec "$chezmoi" "$@"
'''


def run(args):
    """Return (stdout, stderr, status), or None if this subcommand is unsupported."""
    if not args or args[0] != "install.sh":
        return None
    return INSTALL_SH, "", 0

