"""Source-state metadata commands (chattr and forget)."""
import os
import sys


def _target_rel(path, dest):
    p = os.path.abspath(os.path.expanduser(path))
    d = os.path.abspath(os.path.expanduser(dest))
    try:
        return os.path.relpath(p, d)
    except ValueError:
        return path


def _source_entry(source, target):
    """Find a source entry for a destination-relative target."""
    parts = target.replace('\\', '/').split('/')
    candidates = [[]]
    for part in parts:
        names = [part]
        if part.startswith('.'):
            names.insert(0, 'dot_' + part[1:])
        choices = []
        for name in names:
            choices.extend([name, 'private_' + name, 'executable_' + name,
                            'readonly_' + name, 'empty_' + name,
                            'create_' + name, 'modify_' + name,
                            'symlink_' + name,
                            'run_' + name, 'run_once_' + name,
                            'run_onchange_' + name])
            if name.startswith('dot_'):
                choices.extend(['private_' + name, 'executable_' + name])
        candidates = [prefix + [name] for prefix in candidates for name in choices]
    for components in candidates:
        base = os.path.join(source, *components)
        for suffix in ('.tmpl', ''):
            p = base + suffix
            if os.path.lexists(p):
                return p
    # Some targets are stored with attribute prefixes in a different order.
    if os.path.isdir(source):
        for root, dirs, files in os.walk(source):
            for name in files + dirs:
                p = os.path.join(root, name)
                rel = os.path.relpath(p, source)
                decoded = []
                for part in rel.split(os.sep):
                    if part.endswith('.tmpl'):
                        part = part[:-5]
                    for prefix in ('private_', 'executable_', 'readonly_', 'empty_', 'create_', 'modify_', 'run_once_', 'run_onchange_', 'run_'):
                        if part.startswith(prefix):
                            part = part[len(prefix):]
                    if part.startswith('dot_'):
                        part = '.' + part[4:]
                    decoded.append(part)
                if '/'.join(decoded) == target.replace('\\', '/'):
                    return p
    return None


def _encode_attribute(name, attribute, enabled):
    prefixes = {'private': 'private_', 'executable': 'executable_', 'readonly': 'readonly_',
                'empty': 'empty_', 'create': 'create_', 'modify': 'modify_',
                'script': 'run_', 'once': 'run_once_', 'onchange': 'run_onchange_', 'symlink': 'symlink_'}
    for prefix in prefixes.values():
        if name.startswith(prefix):
            name = name[len(prefix):]
    p = prefixes.get(attribute)
    if enabled and p:
        name = p + name
    if attribute == 'template':
        if enabled and not name.endswith('.tmpl'):
            name += '.tmpl'
        elif not enabled and name.endswith('.tmpl'):
            name = name[:-5]
    return name


def chattr(source, destination, args, dry_run=False):
    if len(args) < 2:
        return 1, '', 'chezmoi: chattr requires attributes and targets\n'
    modifiers = args[0].split(',')
    rc, out, err = 0, [], []
    for arg in args[1:]:
        target = _target_rel(arg, destination)
        entry = _source_entry(source, target)
        if not entry:
            rc = 1
            err.append(f'chezmoi: {os.path.abspath(os.path.expanduser(arg))}: not managed\n')
            continue
        newname = os.path.basename(entry)
        for mod in modifiers:
            enabled = not (mod.startswith('no') or mod.startswith('-'))
            attr = mod[2:] if mod.startswith('no') else mod[1:] if mod.startswith(('-', '+')) else mod
            attr = {'x': 'executable', 'p': 'private', 'r': 'readonly', 't': 'template', 'o': 'once', 'e': 'empty'}.get(attr, attr)
            newname = _encode_attribute(newname, attr, enabled)
        dest = os.path.join(os.path.dirname(entry), newname)
        if dest != entry and not dry_run:
            try:
                if os.path.lexists(dest):
                    raise FileExistsError(dest)
                os.rename(entry, dest)
            except OSError as e:
                rc = 1
                err.append(f'chezmoi: {e}\n')
    return rc, ''.join(out), ''.join(err)


def forget(source, destination, args, force=False, dry_run=False):
    rc, out, err = 0, [], []
    for arg in args:
        entry = _source_entry(source, _target_rel(arg, destination))
        if not entry:
            rc = 1
            err.append(f'chezmoi: {os.path.abspath(os.path.expanduser(arg))}: not managed\n')
            continue
        if not force:
            err.append(f'Remove {entry}?\nchezmoi: could not open a new TTY: open /dev/tty: no such device or address\n')
            rc = 1
            continue
        if not dry_run:
            try:
                if os.path.isdir(entry) and not os.path.islink(entry):
                    os.rmdir(entry)
                else:
                    os.unlink(entry)
            except OSError as e:
                rc = 1
                err.append(f'chezmoi: {e}\n')
    return rc, ''.join(out), ''.join(err)
"""Source-state serialization used by the dump command."""
import json
import os
import re
import stat


def decode_name(path):
    """Translate chezmoi source naming attributes into a target relative path."""
    parts = path.replace("\\", "/").split("/")
    out = []
    for part in parts:
        if part == ".chezmoiremove":
            continue
        if part.startswith("symlink_"):
            part = part[len("symlink_"):]
        for prefix in ("private_", "readonly_", "executable_"):
            if part.startswith(prefix):
                part = part[len(prefix):]
                break
        if part.startswith("dot_"):
            part = "." + part[4:]
        if part.endswith(".tmpl"):
            part = part[:-5]
        out.append(part)
    return "/".join(out)


def _render(text, data):
    # Support the common Go-template field and nested-field forms used by
    # chezmoi data templates.
    def sub(m):
        key = m.group(1).strip().lstrip(".").split(".")
        value = data
        for k in key:
            if isinstance(value, dict) and k in value:
                value = value[k]
            else:
                return m.group(0)
        return str(value)
    return re.sub(r"{{\s*\.([A-Za-z_][\w.]*)\s*}}", sub, text)


def _ignored(relative, patterns):
    for pat in patterns:
        pat = pat.strip()
        if not pat or pat.startswith("#"):
            continue
        if relative == pat or relative.endswith("/" + pat) or os.path.basename(relative) == pat:
            return True
    return False


def load_targets(source, data=None):
    data = dict(data or {})
    # Data files are merged in lexical order; JSON is the common bundled form.
    for filename in sorted(os.listdir(source)) if os.path.isdir(source) else []:
        if filename.startswith(".chezmoidata."):
            path = os.path.join(source, filename)
            try:
                if filename.endswith(".json"):
                    with open(path, encoding="utf-8") as f:
                        value = json.load(f)
                    if isinstance(value, dict):
                        data.update(value)
            except (OSError, ValueError):
                pass
    ignorefile = os.path.join(source, ".chezmoiignore")
    try:
        patterns = open(ignorefile, encoding="utf-8").read().splitlines()
    except OSError:
        patterns = []
    result = {}
    if not os.path.isdir(source):
        return result
    for root, dirs, files in os.walk(source):
        dirs[:] = sorted(d for d in dirs if d != ".git" and not d.startswith(".chezmoi"))
        for name in sorted(files):
            src = os.path.join(root, name)
            rawrel = os.path.relpath(src, source).replace(os.sep, "/")
            if name.startswith(".chezmoi"):
                continue
            rel = decode_name(rawrel)
            if _ignored(rel, patterns):
                continue
            mode = os.lstat(src).st_mode
            if stat.S_ISLNK(mode):
                result[rel] = {"type": "symlink", "name": rel,
                               "linkname": os.readlink(src)}
                continue
            rawname = rawrel.split("/")[-1]
            if rawname.startswith("symlink_"):
                try:
                    linkname = open(src, encoding="utf-8").read().rstrip("\n")
                except OSError:
                    linkname = ""
                result[rel] = {"type": "symlink", "name": rel,
                               "linkname": linkname}
                continue
            try:
                content = open(src, "rb").read().decode("utf-8")
            except (OSError, UnicodeDecodeError):
                continue
            attrs = rawrel.split("/")[-1]
            if attrs.endswith(".tmpl"):
                attrs = attrs[:-5]
            if attrs.startswith(("private_", "readonly_", "executable_")):
                attrs = attrs.split("_", 1)[1]
            if name.endswith(".tmpl"):
                content = _render(content, data)
            perm = stat.S_IMODE(mode)
            if rawname.startswith("private_"):
                perm = (perm & 0o111) | (perm & 0o600)
            elif rawname.startswith("readonly_"):
                perm &= 0o555
            elif rawname.startswith("executable_"):
                perm |= 0o111
            result[rel] = {"type": "file", "name": rel,
                           "contents": content, "perm": perm}
    return dict(sorted(result.items()))
