            i += 1
        elif a.startswith(('--include=', '--exclude=')):
            pass
        elif a.startswith('-'):
            pass
        else:
            targets.append(a)
        i += 1

    dst = os.path.abspath(os.path.expanduser(destination))
    entries = dump_command.load_targets(source)
    if targets:
        selected = {}
        for key, value in entries.items():
            for target in targets:
                path = os.path.expanduser(target)
                if os.path.isabs(path):
                    try:
                        path = os.path.relpath(path, dst)
                    except ValueError:
                        continue
                path = os.path.normpath(path).replace(os.sep, '/')
                if key == path or (recursive and key.startswith(path.rstrip('/') + '/')):
                    selected[key] = value
        entries = selected

    # Apply's verbose dry run is a unified diff of all pending target changes.
    if dry_run:
        if verbose:
            import diff_command
            buf = io.StringIO()
            with contextlib.redirect_stdout(buf):
                diff_command.run(source, dst, targets=targets or None)
            return buf.getvalue(), '', 0
        return '', '', 0

    errors = []
    for rel, entry in entries.items():
        path = os.path.join(dst, *rel.split('/'))
        try:
            if entry['type'] == 'symlink':
                os.makedirs(os.path.dirname(path), exist_ok=True)
                if os.path.lexists(path):
                    if os.path.islink(path) and os.readlink(path) == entry['linkname']:
                        continue
                    if os.path.isdir(path) and not os.path.islink(path):
                        raise IsADirectoryError(path)
                    os.unlink(path)
                os.symlink(entry['linkname'], path)
            else:
